parameters.jsCode:
const item = $('Edit Fields5').first().json;
const output = item.output;

// normaliza asteriscos duplicados
function limparTexto(texto) {
  return String(texto || "")
    .replace(/\*+\*/g, "*")
    .trim();
}

// quebra texto grande em blocos por linha em branco
function quebrarTexto(texto) {
  return limparTexto(texto)
    .split("\n\n")
    .map(t => t.trim())
    .filter(t => t !== "");
}

// CASO 1: veio como objeto com campo mensagens (array) — formato atual dos especialistas
if (output && typeof output === "object" && Array.isArray(output.mensagens)) {
  return output.mensagens
    .map((msg, index) => {
      const texto = limparTexto(msg?.texto);
      if (!texto) return null;
      return {
        json: {
          numero: msg?.numero || index + 1,
          texto
        }
      };
    })
    .filter(Boolean);
}

// CASO 2: já veio como array de mensagens (formato legado, ex.: VITA RESPONDE)
if (Array.isArray(output)) {
  return output
    .map((msg, index) => {
      const texto = limparTexto(msg?.texto || msg);
      if (!texto) return null;
      return {
        json: {
          numero: msg?.numero || index + 1,
          texto
        }
      };
    })
    .filter(Boolean);
}

// CASO 3: veio como string direta
if (typeof output === "string") {
  return quebrarTexto(output).map((parte, index) => ({
    json: {
      numero: index + 1,
      texto: parte
    }
  }));
}

// CASO 4: veio como objeto com campo texto
if (output && typeof output === "object" && typeof output.texto === "string") {
  return quebrarTexto(output.texto).map((parte, index) => ({
    json: {
      numero: index + 1,
      texto: parte
    }
  }));
}

// CASO 5: fallback
return [
  {
    json: {
      numero: 1,
      texto: ""
    }
  }
];

parameters.text:
Analise a imagem ou documento médico enviado.

Identifique o tipo de conteúdo, como:
- pedido de exames;
- resultado de exames;
- laudo ou relatório médico;
- receita médica;
- encaminhamento;
- atestado;
- lista ou foto de medicamentos;
- prescrição de suplementos;
- documento de alta ou orientação médica;
- outro documento relacionado à saúde.

Transcreva fielmente todas as informações legíveis, preservando nomes, datas, exames, resultados, valores, unidades, referências, medicamentos, doses e posologias.

Se for uma fotografia clínica, descreva apenas o que estiver visível, sem diagnosticar.

Use [ilegível] ou [incerto] quando não conseguir confirmar uma informação.

Não invente, complete ou interprete clinicamente. Responda em português.

