// ======================================================
// 1. ENTRADAS
// ======================================================

const resultadoAgenda = $input.first().json;

const resultadoFeriado =
  $('verifica_feriado').first().json;

const payload =
  $('payload_webhook').first().json;

const dataRecebida =
  String(payload.data || '');

const hoje = dataRecebida.includes('/')
  ? dataRecebida.split('/').reverse().join('-')
  : dataRecebida.slice(0, 10);

const horaAtual =
  String(payload.time || '00:00').slice(0, 5);

const agora =
  new Date(`${hoje}T${horaAtual}:00-03:00`);

if (Number.isNaN(agora.getTime())) {
  throw new Error(
    `Data ou hora atual inválida: ${hoje} ${horaAtual}`
  );
}

const datasSolicitadas =
  $('Entende_Contexto')
    .first()
    .json
    .output
    .consulta_agenda
    .datas_especificas || [];

const consultaAgenda =
  $('Entende_Contexto')
    .first()
    .json
    .output
    .consulta_agenda || {};

const primeiroEncontro =
  String(consultaAgenda.servico || '')
    .trim()
    .toLowerCase() ===
  'primeiro encontro do mapeamento programa';

const buscaAutomatica =
  resultadoFeriado.busca_automatica === true;

// ======================================================
// 2. TRATAMENTO DE ERRO DA AGENDA
// ======================================================

const resultados =
  Array.isArray(resultadoAgenda.data)
    ? resultadoAgenda.data
    : [];

const erroAgenda =
  resultadoAgenda.status_execucao === 'erro'
    ? resultadoAgenda
    : resultados.find(item =>
        item?.status_execucao === 'erro' ||
        item?.error
      );

if (erroAgenda) {
  return [
    {
      json: {
        status_execucao: 'erro',

        error:
          erroAgenda.error ||
          'Não foi possível consultar a agenda.'
      }
    }
  ];
}


// ======================================================
// 3. REGRAS DA AGENDA
// ======================================================

// Horário permitido para início do atendimento
const INICIO_PERMITIDO = '09:00';

const ULTIMO_INICIO_PERMITIDO =
  primeiroEncontro
    ? '16:00'
    : '17:00';

const antecedenciaPorDia = {
  1: 120,  // segunda
  2: 120,  // terça
  3: 1440, // quarta
  4: 120,  // quinta
  5: 1440  // sexta
};


function criarDataHora(data, hora) {
  return new Date(
    `${data}T${hora}:00-03:00`
  );
}


function formatarHora(data) {
  return data.toLocaleTimeString(
    'pt-BR',
    {
      timeZone: 'America/Sao_Paulo',
      hour: '2-digit',
      minute: '2-digit',
      hour12: false
    }
  );
}


// ======================================================
// 4. APLICAR AS REGRAS AOS INTERVALOS
// ======================================================

const dadosProcessados = resultados

  // Hoje não entra apenas como alternativa
  .filter(item => {
    const data =
      item.periodo_consultado?.data_inicio;

    if (!data) {
      return false;
    }

    const foiSolicitada =
      datasSolicitadas.includes(data);

 return !(
  data === hoje &&
  !foiSolicitada &&
  !buscaAutomatica
);
  })

  .map(item => {
    const data =
      item.periodo_consultado.data_inicio;

    const diaSemana =
      new Date(
        `${data}T12:00:00Z`
      ).getUTCDay();

  const antecedenciaMinima =
  primeiroEncontro
    ? 180
    : antecedenciaPorDia[diaSemana];

    const intervalosRecebidos =
      Array.isArray(item.horarios_livres)
        ? item.horarios_livres.filter(
            intervalo =>
              intervalo &&
              typeof intervalo === 'object' &&
              intervalo.inicio &&
              intervalo.fim
          )
        : [];

    if (antecedenciaMinima === undefined) {
      return {
        ...item,

        janela_inicio_permitido: {
          inicio: INICIO_PERMITIDO,
          fim: ULTIMO_INICIO_PERMITIDO
        },

        horarios_livres: [
          'intervalo_indisponivel'
        ]
      };
    }

    const limiteAntecedencia =
      new Date(
        agora.getTime() +
        antecedenciaMinima * 60000
      );

    const inicioPermitido =
      criarDataHora(
        data,
        INICIO_PERMITIDO
      );

    const ultimoInicioPermitido =
      criarDataHora(
        data,
        ULTIMO_INICIO_PERMITIDO
      );

    const horariosLivres =
      intervalosRecebidos
        .map(intervalo => {
          const inicioOriginal =
            criarDataHora(
              data,
              intervalo.inicio
            );

          const fimOriginal =
            criarDataHora(
              data,
              intervalo.fim
            );

          if (
            Number.isNaN(inicioOriginal.getTime()) ||
            Number.isNaN(fimOriginal.getTime())
          ) {
            return null;
          }

          const inicioAjustado =
            new Date(
              Math.max(
                inicioOriginal.getTime(),
                inicioPermitido.getTime(),
                limiteAntecedencia.getTime()
              )
            );

          if (
            inicioAjustado >= fimOriginal ||
            inicioAjustado > ultimoInicioPermitido
          ) {
            return null;
          }

          return {
            inicio:
              formatarHora(inicioAjustado),

            fim:
              intervalo.fim
          };
        })

        .filter(Boolean);

    return {
      ...item,

      janela_inicio_permitido: {
        inicio: INICIO_PERMITIDO,
        fim: ULTIMO_INICIO_PERMITIDO
      },

      horarios_livres:
        horariosLivres.length > 0
          ? horariosLivres
          : ['intervalo_indisponivel']
    };
  });


// ======================================================
// 5. ALTERNATIVAS DE DATA
// ======================================================

const alteracoesDatas = (
  resultadoFeriado.alteracoes_datas || []
).map(item => ({
  ...item,

  data_valida_anterior:
    item.data_valida_anterior &&
    item.data_valida_anterior > hoje
      ? item.data_valida_anterior
      : null
}));


// ======================================================
// 6. SAÍDA
// ======================================================

return [
  {
    json: {
      status_execucao: 'sucesso',

      local:
        resultadoFeriado.local || null,

      duracao_minutos: 60,

      tempo_pos_atendimento: 0,

      data:
        dadosProcessados,

      alteracoes_datas:
        alteracoesDatas
    }
  }
];

