// =====================================================

function converterDataHoraBR(valor) {
  if (!valor || typeof valor !== "string") return null;

  const [data, hora = "00:00:00"] = valor.trim().split(" ");

  const [dia, mes, ano] = data.split("/").map(Number);
  const [HH = 0, MM = 0, SS = 0] = hora.split(":").map(Number);

  if (!dia || !mes || !ano) return null;

  const dataConvertida = new Date(ano, mes - 1, dia, HH, MM, SS);

  return Number.isNaN(dataConvertida.getTime()) ? null : dataConvertida;
}


