function cell(valor) {

  if (typeof valor === 'boolean') {
    return {
      userEnteredValue: {
        boolValue: valor
      }
    };
  }

  if (typeof valor === 'number') {
    return {
      userEnteredValue: {
        numberValue: valor
      }
    };
  }

  if (Array.isArray(valor)) {
    return {
      userEnteredValue: {
        stringValue: JSON.stringify(valor)
      }
    };
  }

  if (
    valor &&
    typeof valor === 'object'
  ) {
    return {
      userEnteredValue: {
        stringValue: JSON.stringify(valor)
      }
    };
  }

  return {
